// REA UI backend: a local HTTP server that fronts the `rea` CLI.
//
// Design notes:
//  - The command surface is never hardcoded. public/catalog.json is generated by
//    tools/build-catalog.mjs from the CLI's own --llms / --schema / capabilities
//    output, so all 153 commands stay available without hand-written forms.
//  - Long analyses stream progress over SSE. REA emits newline-delimited
//    {"rea_progress":{...}} objects on stdout, which we forward to the browser.
//  - Every invocation is an isolated child process; nothing is cached between
//    runs, matching the CLI's own "each invocation is a separate process" model.
import { spawn } from "node:child_process";
import { createReadStream, existsSync, readFileSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { extname, join, normalize, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = join(here, "public");
const CATALOG_PATH = join(PUBLIC_DIR, "catalog.json");

// Locate the REA entrypoint. In the portable build dependencies live under
// app/node_modules to keep the package root tidy; in a source checkout they
// sit at ./node_modules. REA_BIN overrides both.
function resolveReaBin() {
  const override = process.env.REA_BIN;
  const candidates = [
    override,
    join(here, "app", "node_modules", "rea-agents", "scripts", "rea.mjs"),
    join(here, "node_modules", "rea-agents", "scripts", "rea.mjs"),
  ].filter(Boolean);
  for (const c of candidates) if (existsSync(c)) return c;
  return null;
}

const REA_BIN = resolveReaBin();
const HOST = process.env.REA_UI_HOST || "127.0.0.1";
const PORT = Number(process.env.REA_UI_PORT || 7823);

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".ico": "image/x-icon",
};

function sendJson(res, code, body) {
  const payload = JSON.stringify(body);
  res.writeHead(code, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
    "cache-control": "no-store",
  });
  res.end(payload);
}

function readBody(req, limitBytes = 4 * 1024 * 1024) {
  return new Promise((resolvePromise, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (c) => {
      size += c.length;
      if (size > limitBytes) {
        reject(new Error("Request body too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      if (!raw) return resolvePromise({});
      try {
        resolvePromise(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

// ---------------------------------------------------------------------------
// Argument construction
// ---------------------------------------------------------------------------

// REA accepts camelCase option names on the command line (--max-heap-mb is
// documented as maxHeapMb in the schema); both spellings work, but we emit the
// kebab form shown in the CLI help so logs stay copy-pasteable.
function toKebab(name) {
  return name.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
}

function coerce(value, schema) {
  if (value === undefined || value === null || value === "") return undefined;
  if (typeof value === "boolean") return value;
  const type = schema?.type;
  if (type === "number" || type === "integer") {
    const n = Number(value);
    return Number.isFinite(n) ? n : undefined;
  }
  if (type === "boolean") {
    if (typeof value === "string") return value === "true" || value === "1";
    return Boolean(value);
  }
  if (Array.isArray(value)) return value.map((v) => String(v));
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

// Build the argv for one run. Positional args come first in schema order,
// then options. Arrays repeat the flag; booleans become presence flags.
export function buildArgs(command, args = {}, options = {}) {
  const argv = [];
  const argSchema = command.args?.properties || {};
  const optSchema = command.options?.properties || {};
  const order = command.args?.required || Object.keys(argSchema);

  for (const key of order) {
    const v = coerce(args[key], argSchema[key]);
    if (v === undefined) continue;
    if (Array.isArray(v)) argv.push(...v);
    else argv.push(String(v));
  }
  for (const [key, raw] of Object.entries(options)) {
    const schema = optSchema[key];
    if (!schema) continue;
    const v = coerce(raw, schema);
    if (v === undefined) continue;
    const flag = `--${toKebab(key)}`;
    if (typeof v === "boolean") {
      if (v) argv.push(flag);
    } else if (Array.isArray(v)) {
      for (const item of v) argv.push(flag, String(item));
    } else {
      argv.push(flag, String(v));
    }
  }
  return argv;
}

function loadCatalog() {
  if (!existsSync(CATALOG_PATH)) return { commands: [], capabilities: null };
  try {
    return JSON.parse(readFileSync(CATALOG_PATH, "utf8"));
  } catch {
    return { commands: [], capabilities: null };
  }
}

function findCommand(name) {
  const cat = loadCatalog();
  return cat.commands.find((c) => c.name === name) || null;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

async function handleRunApi(req, res, body) {
  const { command, args, options, format } = body;
  if (!command) return sendJson(res, 400, { error: "command is required" });
  if (!REA_BIN) {
    return sendJson(res, 500, { error: "rea-agents not found. Set REA_BIN or reinstall the package." });
  }
  const cmd = findCommand(command);
  const argv = [REA_BIN, command, ...buildArgs(cmd || { args: {}, options: {} }, args, options)];
  if (format && format !== "json") argv.push("--format", format);
  argv.push("--json");

  res.writeHead(200, {
    "content-type": "text/event-stream; charset=utf-8",
    "cache-control": "no-cache",
    connection: "keep-alive",
    "x-accel-buffering": "no",
  });

  const child = spawn(process.execPath, argv, { windowsHide: true });
  let finished = false;
  // stdout carries the result envelope and progress objects; REA writes them as
  // newline-delimited JSON but does not guarantee one write per line, so partial
  // lines must be buffered until the next newline arrives.
  let stdoutBuf = "";

  const emit = (event, data) => {
    if (finished) return;
    res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  };

  const handleLine = (line) => {
    const t = line.trim();
    if (!t) return;
    if (t.startsWith("{")) {
      try {
        const parsed = JSON.parse(t);
        emit(parsed.rea_progress ? "progress" : "result", parsed);
        return;
      } catch {
        /* not complete JSON yet — treat as raw text */
      }
    }
    emit("log", { line: t });
  };

  child.stdout.on("data", (chunk) => {
    stdoutBuf += chunk.toString("utf8");
    const lines = stdoutBuf.split("\n");
    stdoutBuf = lines.pop() ?? "";
    for (const line of lines) handleLine(line);
  });

  let stderrBuf = "";
  child.stderr.on("data", (chunk) => {
    stderrBuf += chunk.toString("utf8");
    const lines = stderrBuf.split("\n");
    stderrBuf = lines.pop() ?? "";
    for (const raw of lines) {
      const line = raw.trim();
      if (!line) continue;
      // REA reports progress on stderr as rea_progress objects.
      if (line.startsWith("{")) {
        try {
          const parsed = JSON.parse(line);
          if (parsed.rea_progress) {
            emit("progress", parsed);
            continue;
          }
        } catch {
          /* fall through */
        }
      }
      emit("stderr", { line });
    }
  });

  child.on("error", (err) => {
    finished = true;
    emit("failed", { error: String(err.message || err) });
    res.end();
  });

  child.on("close", (code) => {
    // Flush trailing output BEFORE marking finished, otherwise the buffered
    // remainder (and the done event itself) would be dropped.
    if (stdoutBuf.trim()) handleLine(stdoutBuf);
    if (stderrBuf.trim()) emit("stderr", { line: stderrBuf.trim() });
    emit("done", { exitCode: code });
    finished = true;
    res.end();
  });

  req.on("close", () => {
    if (!finished && !child.killed) child.kill();
  });
}

// Minimal tool loop for the conversational panel: the model may ask to run a REA
// command, we execute it and hand the (trimmed) result back as a tool message.
async function handleChatApi(req, res, body) {
  const { messages, apiKey, baseUrl, model } = body;
  if (!Array.isArray(messages) || !messages.length) {
    return sendJson(res, 400, { error: "messages is required" });
  }
  if (!apiKey) return sendJson(res, 400, { error: "apiKey is required" });

  const cat = loadCatalog();
  const toolList = cat.commands
    .map((c) => {
      const reqArgs = (c.args?.required || []).join(", ");
      const optNames = Object.keys(c.options?.properties || {})
        .map(toKebab)
        .map((n) => `--${n}`)
        .join(" ");
      return `- rea ${c.name}${reqArgs ? " " + reqArgs : ""}${optNames ? " [" + optNames + "]" : ""} — ${c.description}`;
    })
    .join("\n");

  const system = [
    "You are the assistant inside REA UI, a graphical front-end for the REA reverse-engineering CLI.",
    "You can run REA commands by replying with a fenced ```rea block containing one command line.",
    "Use absolute Windows paths. Only one command per block. Wait for the result before the next command.",
    "Cite evidence from the tool result; state limitations explicitly.",
    "",
    "Available REA commands:",
    toolList,
  ].join("\n");

  const endpoint = `${(baseUrl || "https://api.openai.com/v1").replace(/\/$/, "")}/chat/completions`;
  const messagesForApi = [{ role: "system", content: system }, ...messages];

  try {
    const upstream = await fetch(endpoint, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: model || "gpt-4o-mini",
        messages: messagesForApi,
        temperature: 0.2,
        stream: false,
      }),
    });
    const data = await upstream.json();
    if (!upstream.ok) {
      return sendJson(res, 502, { error: data?.error?.message || `HTTP ${upstream.status}` });
    }
    sendJson(res, 200, { reply: data.choices?.[0]?.message?.content || "" });
  } catch (err) {
    sendJson(res, 502, { error: String(err.message || err) });
  }
}

async function runReaToJson(args, timeoutMs = 60000) {
  if (!REA_BIN) throw new Error("rea-agents not found");
  return new Promise((resolvePromise, reject) => {
    const child = spawn(process.execPath, [REA_BIN, ...args, "--json"], { windowsHide: true });
    let out = "";
    let err = "";
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error("REA command timed out"));
    }, timeoutMs);
    child.stdout.on("data", (d) => (out += d));
    child.stderr.on("data", (d) => (err += d));
    child.on("close", (code) => {
      clearTimeout(timer);
      try {
        const parsed = JSON.parse(out);
        resolvePromise({ code, data: parsed });
      } catch {
        resolvePromise({ code, data: null, raw: out, stderr: err });
      }
    });
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  try {
    if (path === "/api/catalog") {
      return sendJson(res, 200, loadCatalog());
    }

    if (path === "/api/env") {
      return sendJson(res, 200, {
        reaAvailable: Boolean(REA_BIN),
        reaBin: REA_BIN,
        node: process.version,
        pid: process.pid,
        platform: process.platform,
      });
    }

    if (path === "/api/providers" && req.method === "GET") {
      const { code, data, raw, stderr } = await runReaToJson(["providers"]);
      return sendJson(res, 200, { exitCode: code, data, raw, stderr });
    }

    if (path === "/api/doctor" && req.method === "POST") {
      const body = await readBody(req);
      const argv = ["doctor"];
      if (body.provider) argv.push("--provider", body.provider);
      const { code, data, raw, stderr } = await runReaToJson(argv);
      return sendJson(res, 200, { exitCode: code, data, raw, stderr });
    }

    if (path === "/api/run" && req.method === "POST") {
      return await handleRunApi(req, res, await readBody(req));
    }

    if (path === "/api/chat" && req.method === "POST") {
      return await handleChatApi(req, res, await readBody(req));
    }

    if (path === "/api/browse" && req.method === "POST") {
      const body = await readBody(req);
      const target = resolve(String(body.path || ""));
      if (!existsSync(target)) return sendJson(res, 404, { error: "path not found" });
      const st = statSync(target);
      return sendJson(res, 200, {
        path: target,
        name: target.split(/[\\/]/).pop(),
        isDirectory: st.isDirectory(),
      });
    }

    // static files
    let rel = path === "/" ? "/index.html" : path;
    rel = normalize(rel).replace(/^([/\\])+/, "");
    const file = resolve(join(PUBLIC_DIR, rel));
    if (!file.startsWith(resolve(PUBLIC_DIR))) {
      return sendJson(res, 403, { error: "forbidden" });
    }
    if (!existsSync(file) || !statSync(file).isFile()) {
      return sendJson(res, 404, { error: "not found" });
    }
    res.writeHead(200, {
      "content-type": MIME[extname(file).toLowerCase()] || "application/octet-stream",
    });
    createReadStream(file).pipe(res);
  } catch (err) {
    if (!res.headersSent) sendJson(res, 500, { error: String(err.message || err) });
    else res.end();
  }
});

server.listen(PORT, HOST, () => {
  const cat = existsSync(CATALOG_PATH) ? loadCatalog() : { commandCount: 0 };
  console.log(`REA UI  ->  http://${HOST}:${PORT}`);
  console.log(`commands in catalog: ${cat.commandCount || 0}`);
  console.log(`rea binary: ${REA_BIN || "NOT FOUND"}`);
  if (process.env.REA_UI_OPEN === "1") {
    spawn("cmd", ["/c", "start", "", `http://${HOST}:${PORT}`], {
      detached: true,
      stdio: "ignore",
      windowsHide: true,
    }).unref();
  }
});
